"""
Evaluate moving-reference residual forces and Hessians through second parameter order.

In the anchored canonical frame, reconstruct the molecular geometry using

$$r(\lambda)=r_*(\lambda)+B(\lambda)q(\lambda),\qquad

\delta r=Bq,$$

so that

$$r'=r_*'+B'q+Bq',\qquad

r''=r_*''+B''q+2B'q'+Bq''.$$

The source propagator separates the exact harmonic reference from the remainder. With $g=\nabla V_\lambda(r)$ and $H(r,\lambda)=\nabla^2V_\lambda(r)$, the modal residual force and its position Jacobian are

$$s=B^T[-g+H_*\delta r],\qquad G=B^T[H_*-H(r,\lambda)]B.$$

The positive baseline term removes the harmonic force already represented by the exact drift. All terms are evaluated at the reconstructed band geometry, and the stationary reference satisfies $\nabla V_\lambda(r_*)=0$.



The force and Jacobian jets are total parameter derivatives along the supplied $q(\lambda)$, rather than partial derivatives at fixed positions. Raw derivative products satisfy

$$ (UV)^{[j]}=\sum_{\ell=0}^j\binom j\ell U^{[\ell]}V^{[j-\ell]},\qquad j=0,1,2.$$

For example, the second derivative of a quartic channel gradient contains moving-coordinate terms from $u^3$, explicit coefficient derivatives, and their mixed products. The second total derivative of $G$ additionally contracts the fourth derivative of the potential with the first position response. These responses must include the changing left projection $B^T$, the changing reconstruction $Bq$, and the relaxed Hessian $H_*$; holding any of them fixed changes the physical perturbation.

Returns
-------
np.ndarray, shape (3,k,k+1), total residual-force and modal-Jacobian derivative layers.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def projected_force_response(
    eq: "np.ndarray",
    ref: "np.ndarray",
    A: "np.ndarray",
    C: "np.ndarray",
    cubic: "np.ndarray",
    beta: "np.ndarray",
    force: "np.ndarray",
    qjet: "np.ndarray",
) -> "np.ndarray":
    r"""Evaluate moving-reference residual forces and Hessians through second parameter order.

    Parameters
    ----------
    eq : np.ndarray
        Shape (3,s,s+1), relaxed geometry and Hessian jets.
    ref : np.ndarray
        Shape (3,k+s,k), stiffness jets followed by reconstruction B jets.
    A, C, cubic, beta, force : np.ndarray
        Static potential arrays with shapes (3,s,s), (j,s), (j,), (3,j), (3,s).
        V=r.T*A(lambda)*r/2-force(lambda).T*r+
        sum_j[cubic_j*(c_j.r)^3/3+beta_j(lambda)*(c_j.r)^4/4].
    qjet : np.ndarray
        Shape (3,k), current band positions and their two total parameter derivatives.

    Returns
    -------
    result, np.ndarray
        Shape (3,k,k+1), first column is the total residual-force jet along qjet;
        other columns are total derivatives of its modal position Jacobian.
        The full force is evaluated at r_star+B*q and the reference harmonic
        force is removed before projection. External driving is excluded.

    All derivative arrays have leading axis (value, first derivative, second derivative) at lambda=0, with no factorial scaling. All data are real, finite, and conforming; inputs must be preserved.
    """
    return result

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np


def _oracle_projected_force_response(
    eq: "np.ndarray",
    ref: "np.ndarray",
    A: "np.ndarray",
    C: "np.ndarray",
    cubic: "np.ndarray",
    beta: "np.ndarray",
    force: "np.ndarray",
    qjet: "np.ndarray",
) -> "np.ndarray":
    k = qjet.shape[1]
    B = ref[:, k:]
    displacement = _jmat(B, qjet)
    r = eq[:, :, 0] + displacement
    t = r @ C.T
    t2 = _jmul(t, t)
    t3 = _jmul(t2, t)
    grad = _jmat(A, r) - force + (cubic * t2 + _jmul(beta, t3)) @ C
    hweights = 2 * cubic * t + 3 * _jmul(beta, t2)
    H = A + np.stack([C.T @ (v[:, None] * C) for v in hweights])
    Href = eq[:, :, 1:]
    f = _jmat(_jtranspose(B), -grad + _jmat(Href, displacement))
    G = _jmat(_jtranspose(B), _jmat(Href - H, B))
    return np.concatenate((f[:, :, None], G), axis=2)

